insert into public.asset_price_observations(asset_id,source_reference,source_row,listed_amount_l,listed_amount_v,consistency,currency,commercial_unit,observed_at)
select a.id,'Disponible Semana del 06 al 12 de septiembre 2026',s.source_row,s.price_l,s.price_v,case when s.price_l is not null and s.price_v is not null and s.price_l=s.price_v then 'consistent' when s.price_l is null and s.price_v is null then 'missing' when s.price_l is null or s.price_v is null then 'incomplete' else 'conflict' end,'COP',null,'2026-09-06' from source s join public.inventory_assets a on a.canonical_code=s.canonical_code
on conflict(asset_id,source_reference) do update set source_row=excluded.source_row,listed_amount_l=excluded.listed_amount_l,listed_amount_v=excluded.listed_amount_v,consistency=excluded.consistency,observed_at=excluded.observed_at,imported_at=now();
